        for(int i=0;i<ts.Length;i+=3){var a=uvOwner.TransformPoint(vs[ts[i]]);var b=uvOwner.TransformPoint(vs[ts[i+1]]);var c=uvOwner.TransformPoint(vs[ts[i+2]]);var normal=Vector3.Cross(b-a,c-a).normalized;if(normal.y<.95f)continue;float det=(b.x-a.x)*(c.z-a.z)-(c.x-a.x)*(b.z-a.z);if(Mathf.Abs(det)<1e-6f)continue;var start=uv[ts[i]];var v=uv[ts[i+1]]-start;var w=uv[ts[i+2]]-start;var dx=(v*(c.z-a.z)-w*(b.z-a.z))/det;var dz=(w*(b.x-a.x)-v*(c.x-a.x))/det;return world.Select(p=>start+dx*(p.x-a.x)+dz*(p.z-a.z)).ToArray();}
